"""Generate private application bindings for the currently implemented parameter records."""

from __future__ import annotations

import json
from typing import Any

from parameter_cpp import option_id
from parameter_structs import PSF_TYPES, TYPES, psf_groups, psf_members
from parameter_values import invalid

PREAMBLE = (
    "// SPDX-FileCopyrightText: 2026 Ervins Strauhmanis\n"
    "// SPDX-License-Identifier: MPL-2.0\n"
    "// Generated by tools/generate_spec.py from spec/method-contract.json.\n"
    "#pragma once\n"
    '#include "admission.hpp"\n'
    '#include "docenhance/core/result.hpp"\n'
    '#include "docenhance/methods/parameters.hpp"\n'
    "#include <string_view>\n#include <utility>\n#include <variant>\n"
    "namespace docenhance::app {\n"
    "template <typename Parameters>\n"
    "[[nodiscard]] core::Result<Parameters> bind_parameters(const SuppliedOptions& options);\n"
)


def assignment(option: dict[str, Any], target: str) -> str:
    """Each declaration maps to exactly one typed assignment, or the generator refuses it."""
    identity, field, kind = option_id(option), option["field"], option["kind"]
    if kind == "grid":
        return (
            f"assign_grid(options, OptionId::{identity}, "
            f"{target}.{field}_columns, {target}.{field}_rows)"
        )
    if kind == "choice":
        invalid(f"{option['name']}: choice needs its concrete discriminated binding")
    automatic = {"auto_or_integer": "auto", "source_or_decimal": "source"}.get(kind)
    tail = f", {json.dumps(automatic)}" if automatic else ""
    return f"assign_supplied(options, OptionId::{identity}, {target}.{field}{tail})"


def assignments(options: list[dict[str, Any]], target: str) -> str:
    """Refuse the complete local record rather than returning a partial successful copy."""
    if not options:
        return ""
    checks = " ||\n        ".join("!" + assignment(option, target) for option in options)
    return f"    if ({checks}) {{ return binding_error(); }}\n"


def surface_mode(family: dict[str, Any], method: dict[str, Any]) -> str:
    """I01 automatic selection remains the same actual method with its distinct mode value."""
    identity = option_id({"name": family["selector"]["option"]})
    fallback = json.dumps(family["selector"]["default"])
    text = (
        f"    const auto& slot = options.get(OptionId::{identity});\n"
        "    const auto* const supplied = std::get_if<std::string_view>(&slot);\n"
        "    if (supplied == nullptr && !std::holds_alternative<std::monostate>(slot)) {\n"
        "        return binding_error();\n    }\n"
        f"    const std::string_view selected = supplied != nullptr ? *supplied : {fallback};\n"
    )
    for index, (spelling, behavior) in enumerate(method["selectors"].items()):
        mode = (
            "automatic" if behavior.get("mode", "explicit") == "automatic" else "explicit_surface"
        )
        prefix = "if" if index == 0 else "else if"
        text += (
            f"    {prefix} (selected == {json.dumps(spelling)}) {{\n"
            f"        p.mode = methods::SurfaceMode::{mode};\n    }}\n"
        )
    return text + "    else { return binding_error(); }\n"


def psf_binding(parameters: list[dict[str, Any]], by_name: dict[str, dict[str, Any]]) -> str:
    """Bind the required explicit PSF kind and preserve the current owned FilePsf.path."""
    options = [by_name[parameter["option"]] for parameter in parameters]
    groups = psf_groups(options)
    text = (
        "    const auto* const kind = std::get_if<std::string_view>(&options.get(OptionId::psf));\n"
        "    if (kind == nullptr) { return binding_error(); }\n"
    )
    for index, (spelling, type_name) in enumerate(PSF_TYPES):
        prefix = "if" if index == 0 else "else if"
        text += f"    {prefix} (*kind == {json.dumps(spelling)}) {{\n"
        text += f"        methods::{type_name} psf;\n"
        text += assignments(psf_members(spelling, groups[spelling]), "psf")
        text += (
            "        p.psf = "
            + ("std::move(psf)" if spelling == "kernel" else "psf")
            + ";\n    }\n"
        )
    text += "    else { return binding_error(); }\n"
    return text + assignments(groups["common"], "p")


def render_bindings(families: list[dict[str, Any]], options: list[dict[str, Any]]) -> str:
    """Bind current concrete records; new methods still need actual implementations."""
    by_name = {option["name"]: option for option in options}
    text = PREAMBLE
    for family in families:
        for method in family["methods"]:
            identity = method["id"]
            type_name = TYPES[identity]
            members = [by_name[p["option"]] for p in [*family["shared"], *method["parameters"]]]
            argument = "options" if members or identity == "I01" else "/*options*/"
            text += (
                f"template <> inline core::Result<methods::{type_name}>\n"
                f"bind_parameters<methods::{type_name}>(const SuppliedOptions& {argument}) {{\n"
                f"    methods::{type_name} p;\n"
            )
            if identity == "I01":
                text += surface_mode(family, method)
            if identity == "R01":
                text += psf_binding(method["parameters"], by_name)
            else:
                if any(option.get("when") for option in members):
                    invalid(f"{identity}: unsupported conditional binding")
                text += assignments(members, "p")
            text += "    return p;\n}\n"
    return text + "} // namespace docenhance::app\n"
